fn reset_surface_color(glyph: i64) -> i64 {
    if matches!(glyph, OPEN_DOOR_DASH_GLYPH | OPEN_DOOR_BAR_GLYPH | CLOSED_DOOR_DASH_GLYPH | CLOSED_DOOR_BAR_GLYPH | 2384 | 2385) {
        3
    } else {
        7
    }
}

fn object_class_char(class: i64) -> Option<&'static str> {
    match class {
        2 => Some(")"),
        3 => Some("["),
        4 => Some("="),
        5 => Some("\""),
        6 => Some("("),
        7 => Some("%"),
        8 => Some("!"),
        9 => Some("?"),
        10 => Some("+"),
        11 => Some("/"),
        12 => Some("$"),
        13 => Some("*"),
        14 => Some("`"),
        15 => Some("0"),
        16 => Some("_"),
        17 => Some("."),
        _ => None,
    }
}

