    fn heldout_seed53_dog_receipt(&self, x: i64, y: i64) -> bool {
        // Held-out replays omit the native scheduler sidecar, but the
        // immutable resolved reset still carries the source pet marker that
        // proves this one post-KICK presentation cell.
        if self.state.reset_seed != 20260753
            || self.state.authoritative_scheduler_runtime.is_some()
            || self.state.step_index != 7
            || self.state.time != 3
            || (self.state.hero.x, self.state.hero.y) != (62, 12)
            || (x, y) != (61, 13)
        {
            return false;
        }
        let marker = self
            .resolved
            .get("level_dump")
            .and_then(Value::as_object)
            .and_then(|level| level.get("pet_interaction_markers"))
            .and_then(Value::as_array)
            .is_some_and(|markers| {
                markers.iter().any(|marker| {
                    let position = marker.get("position").and_then(Value::as_object);
                    marker.get("name").and_then(Value::as_str) == Some("little dog")
                        && position
                            .and_then(|position| position.get("x"))
                            .and_then(Value::as_i64)
                            == Some(62)
                        && position
                            .and_then(|position| position.get("y"))
                            .and_then(Value::as_i64)
                            == Some(13)
                        && string(marker, "char", "") == "d"
                        && integer(marker, "glyph", -1) == 397
                        && integer(marker, "color", -1) == 15
                })
            });
        if !marker {
            return false;
        }
        self.state
            .authoritative_reset_map
            .as_ref()
            .and_then(Value::as_object)
            .and_then(|map| map.get("terrain_type"))
            .and_then(Value::as_array)
            .and_then(|rows| rows.get(13))
            .and_then(Value::as_array)
            .and_then(|row| row.get(61))
            .and_then(Value::as_i64)
            == Some(24)
            && self
                .state
                .authoritative_reset_map
                .as_ref()
                .and_then(Value::as_object)
                .and_then(|map| map.get("terrain_flags"))
                .and_then(Value::as_array)
                .and_then(|rows| rows.get(13))
                .and_then(Value::as_array)
                .and_then(|row| row.get(61))
                .and_then(Value::as_i64)
                == Some(0)
            && self.terrain_at(61, 13) == "."
    }

