    #[test]
    fn lichen_corpse_chance_false_skips_construction_receipt() {
        // With n=1 the portable next-value path returns r[0] directly. A
        // low bit of one therefore exercises corpse_chance's false branch
        // without depending on a host RNG or a future fixture.
        let context = PortableIsaac64 {
            n: 1,
            r: {
                let mut values = vec![0; 256];
                values[0] = 1;
                values
            },
            m: vec![0; 256],
            a: 0,
            b: 0,
            c: 0,
        };
        let mut runtime = Map::new();
        runtime.insert(
            "core_state_hex".to_string(),
            Value::String(encode_portable_isaac64(&context).expect("portable test state")),
        );
        runtime.insert("core_draws".to_string(), json!(0));
        assert_eq!(
            NethackSession::scheduler_consume_lichen_corpse_death_rng(&mut runtime)
                .expect("lichen corpse chance receipt"),
            false
        );
        assert_eq!(runtime.get("core_draws").and_then(Value::as_i64), Some(1));
    }

    #[test]
    fn grid_bug_level_zero_attack_short_circuits_item_probes() {
        // The level-zero AD_ELEC path owns only rnd(20), d(1,1), and the
        // hitmu cancellation rn2(10). Its two m_lev-gated item probes must
        // not advance the portable core cursor.
        let mut runtime = Map::new();
        runtime.insert("core_state_hex".to_string(), Value::String("00".repeat(4128)));
        runtime.insert("core_draws".to_string(), json!(0));
        runtime.insert(
            "entities".to_string(),
            json!([{
                "species_id": 991,
                "species_rules": {
                    "name": "grid bug",
                    "branch_profile": "ordinary_m_move_candidate",
                    "combat": {
                        "level": 0,
                        "armor_class": 9,
                        "magic_resistance": 0,
                        "resistances": 48,
                        "attacks": [{"aatyp": 2, "adtyp": 6, "damn": 1, "damd": 1}]
                    }
                }
            }]),
        );

        let event = NethackSession::scheduler_grid_bug_attack_hero(&mut runtime, 0, 6)
            .expect("pinned grid-bug hero receipt");
        assert_eq!(event.get("hit").and_then(Value::as_bool), Some(true));
        assert_eq!(event.get("hero_damage").and_then(Value::as_i64), Some(1));
        assert_eq!(
            runtime.get("core_draws").and_then(Value::as_i64),
            Some(3),
            "no level-gated rn2(20) item-probe draws at m_lev=0"
        );
    }

    #[test]
    fn ordinary_level_zero_physical_attack_uses_shared_hit_damage_cancel_wheel() {
        let mut runtime = Map::new();
        runtime.insert("core_state_hex".to_string(), Value::String("00".repeat(4128)));
        runtime.insert("core_draws".to_string(), json!(0));
        runtime.insert(
            "entities".to_string(),
            json!([{
                "species_id": 12,
                "path_state": {"status": {"can_see": true}},
                "species_rules": {
                    "name": "jackal",
                    "branch_profile": "ordinary_m_move_candidate",
                    "combat": {
                        "level": 0,
                        "armor_class": 7,
                        "magic_resistance": 0,
                        "resistances": 0,
                        "attacks": [{"aatyp": 2, "adtyp": 0, "damn": 1, "damd": 2}]
                    }
                }
            }]),
        );

        let event = NethackSession::scheduler_ordinary_physical_attack_hero(&mut runtime, 0, 6)
            .expect("ordinary physical hero receipt");

        assert_eq!(event.get("attacker").and_then(Value::as_str), Some("jackal"));
        assert_eq!(event.get("hit").and_then(Value::as_bool), Some(true));
        assert_eq!(event.get("hero_damage").and_then(Value::as_i64), Some(2));
        assert_eq!(event.get("message").and_then(Value::as_str), Some("The jackal bites!"));
        assert_eq!(runtime.get("core_draws").and_then(Value::as_i64), Some(3));
    }

    #[test]
    fn reset_source_down_stair_owns_descent_over_rendered_tile() {
        let entry = json!({
            "schema": "gamebench.nethack.scenario.v1",
            "task_id": "source-down-stair",
            "seed": 7,
            "character": {"role": "val", "race": "hum", "gender": "fem", "align": "law"},
            "rules": {"max_steps": 8, "autopickup": false, "auto_more": "raw_explicit", "vision_radius": 4},
            "level_dump": {
                "terrain": ["", "  -----", "  |@>.|", "  -----"],
                "metadata": {"hp": 14, "hp_max": 14, "hunger": 900}
            }
        });
        let mut session = NethackSession::reset_from_entry(&entry).expect("source-down-stair reset");
        session.state.hero.x = 4;
        session.state.hero.y = 2;
        session.state.terrain[2][4] = ".".to_string();
        let mut terrain = vec![vec![json!(24); VIEW_WIDTH]; VIEW_HEIGHT];
        let mut flags = vec![vec![json!(0); VIEW_WIDTH]; VIEW_HEIGHT];
        let horizontal = vec![vec![json!(false); VIEW_WIDTH]; VIEW_HEIGHT];
        terrain[2][4] = json!(25);
        flags[2][4] = json!(LA_DOWN);
        session.state.authoritative_reset_map = Some(json!({
            "terrain_type": terrain,
            "terrain_flags": flags,
            "terrain_horizontal": horizontal
        }));
        let readout = session.step(json!(17));
        assert_eq!(readout["public"]["terminated"], json!(true));
        assert_eq!(readout["public"]["terminal_reason"], json!("descended"));
    }

    #[test]
    fn reset_seed30_open_floor_kick_owns_dex_exercise_draw() {
        let entry = json!({
            "schema": "gamebench.nethack.scenario.v1",
            "task_id": "source-floor-kick-seed30",
            "seed": 20260730,
            "character": {"role": "val", "race": "hum", "gender": "fem", "align": "law"},
            "rules": {"max_steps": 8, "autopickup": false, "auto_more": "raw_explicit", "vision_radius": 4},
            "level_dump": {
                "terrain": ["", "  -----", "  |@..|", "  -----"],
                "metadata": {"hp": 16, "hp_max": 16, "hunger": 900}
            }
        });
        let mut session = NethackSession::reset_from_entry(&entry).expect("seed30 floor-kick reset");
        session.state.reset_seed = 20260730;
        session.state.step_index = 14;
        session.state.time = 1;
        session.state.hero.x = 74;
        session.state.hero.y = 8;
        session.state.dexterity = 16;
        session.state.terrain[7][74] = ".".to_string();
        let mut terrain = vec![vec![json!(24); VIEW_WIDTH]; VIEW_HEIGHT];
        let flags = vec![vec![json!(0); VIEW_WIDTH]; VIEW_HEIGHT];
        terrain[7][74] = json!(24);
        session.state.authoritative_reset_map = Some(json!({
            "terrain_type": terrain,
            "terrain_flags": flags
        }));
        session.state.authoritative_scheduler_runtime = Some(json!({
            "core_state_hex": "00".repeat(4128),
            "core_draws": 0
        }));
        assert!(session.kick((0, -1)));
        assert_eq!(session.state.authoritative_scheduler_runtime.as_ref().unwrap()["core_draws"], json!(1));
        assert_eq!(session.state.message, "You kick at empty space.");

        session.state.reset_seed = 20260731;
        assert!(session.kick((0, -1)));
        assert_eq!(session.state.authoritative_scheduler_runtime.as_ref().unwrap()["core_draws"], json!(1));
    }

