    #[test]
    fn legacy_pet_visibility_uses_source_insight_plane() {
        let entry = json!({
            "schema": "gamebench.nethack.scenario.v1",
            "task_id": "legacy-pet-insight",
            "seed": 7,
            "character": {"role": "val", "race": "hum", "gender": "fem", "align": "law"},
            "rules": {"max_steps": 8, "autopickup": false, "auto_more": "raw_explicit", "vision_radius": 4},
            "level_dump": {
                "terrain": ["", "  -----", "  |@..|", "  -----"],
                "metadata": {"hp": 14, "hp_max": 14, "hunger": 900}
            }
        });
        let mut session = NethackSession::reset_from_entry(&entry).expect("legacy insight reset");
        let mut insight = vec![vec![false; VIEW_WIDTH]; VIEW_HEIGHT];
        insight[4][4] = true;
        session.state.source_fov_insight = Some(insight);
        session.state.authoritative_scheduler_runtime = Some(json!({
            "dynamic_enabled": true,
            "legacy_static_surface": true
        }));
        assert!(session.dynamic_pet_visible_at(4, 4));
        assert!(!session.dynamic_pet_visible_at(5, 4));
    }
